-- Notification templates for the job offers and job applications modules
	-- Job offer - Notification - Expired closing date and not closed status - Assigned user
    ('d3c1d5b7-f8d2-4df4-9f6b-2c63aa6b8e41', NOW(), NOW(), '1', '1', NULL, 'Example - Job offer with expired closing date without closed status (assigned user)', 'Notification to the assigned user that the offer has already expired and is not closed.', 'Job offer out of deadline:  $stic_job_offers_name', '$stic_job_offers_assigned_user_name:\r\n\r\nThe job offer $stic_job_offers_name has an expired application closing date and is currently in status $stic_job_offers_status.\r\n\r\nPlease review it and, if appropriate, update its status: $sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id', '<p>$stic_job_offers_assigned_user_name:</p>\n<p>The job offer <strong>$stic_job_offers_name</strong> has an expired application closing date and is currently in status <strong>$stic_job_offers_status</strong>.</p>\n<p><a href="$sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id">Review it</a> and, if appropriate, update its status.</p>', 0, '1', 0, 'notification'),
    -- Job offer - Notification - Expired closing date and not closed status - Interlocutor
    ('c2a9e9d1-1f5f-4c6c-9b3c-8d3c2a7f4b81', NOW(), NOW(), '1', '1', NULL, 'Example - Job offer with expired closing date without closed status (interlocutor)', 'Notification to the interlocutor that the offer has already expired and is not closed.', 'Job offer out of deadline: $stic_job_offers_name', 'Dear $contact_name:\r\n\r\nThe job offer $stic_job_offers_name has an expired application closing date and is currently in status $stic_job_offers_status.\r\n\r\nPlease review it and, if appropriate, update its status: $portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id', '<p>Dear $contact_name:</p>\n<p>The job offer <strong>$stic_job_offers_name</strong> has an expired application closing date and is currently in status <strong>$stic_job_offers_status</strong>.</p>\n<p><a href="$portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id">Review it</a> and, if appropriate, update its status.</p>', 0, '1', 0, 'notification'),
    -- Accepted application - Assigned user 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0001', NOW(), NOW(), '1', '1', NULL, 'Example - Application accepted (assigned user)', 'Notification to the assigned user when an application changes to Accepted.', 'Application accepted: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\nThe application of $stic_job_applications_stic_job_applications_contacts_name for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has been accepted.\r\n\r\nLink to the application: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p>The application of <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has been <strong>accepted</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Accepted application - Candidate 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0002', NOW(), NOW(), '1', '1', NULL, 'Example - Application accepted (candidate)', 'Notification to the candidate when an application changes to Accepted.', 'Application accepted: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $stic_job_applications_stic_job_applications_contacts_name:\r\n\r\nWe are pleased to inform you that your application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has been accepted.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $stic_job_applications_stic_job_applications_contacts_name:</p><p>We are pleased to inform you that your application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has been <strong>accepted</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Rejected or closed application - Assigned user 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0004', NOW(), NOW(), '1', '1', NULL, 'Example - Application rejected/closed (assigned user)', 'Notification to the assigned user when an application changes to Rejected or closed.', 'Application rejected or closed: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\n\nThe application of $stic_job_applications_stic_job_applications_contacts_name for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has been rejected.\r\n\r\nLink to the application: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p>The application of <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has been rejected.</p><p><a href=\"$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id\">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Rejected or closed application - Candidate 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0005', NOW(), NOW(), '1', '1', NULL, 'Example - Application rejected/closed (candidate)', 'Notification to the candidate when an application changes to Rejected or closed.', 'Application rejected: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $stic_job_applications_stic_job_applications_contacts_name:\n\nWe appreciate your interest in the offer $stic_job_applications_stic_job_applications_stic_job_offers_name.\n\nUnfortunately, on this occasion it has been decided to continue the process with other applications that more closely match the characteristics of the offer.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $stic_job_applications_stic_job_applications_contacts_name:</p><p>We appreciate your interest in the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p>Unfortunately, on this occasion it has been decided to continue the process with other applications that more closely match the characteristics of the offer.</p><p><a href=\"$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id\">Link to the application</a>.</p><p>We wish you great success. Sincerely, $stic_job_offers_stic_job_offers_accounts_name</p>', 0, '1', 0, 'notification'),
    -- Other application statuses - Assigned user 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0007', NOW(), NOW(), '1', '1', NULL, 'Example - Application other statuses (assigned user)', 'Notification to the assigned user when an application changes to Pending interview or Interviewed.', 'Application $stic_job_applications_status: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\nThe application of $stic_job_applications_stic_job_applications_contacts_name for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has changed to $stic_job_applications_status.\r\n\r\nLink to the application: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name,</p><p>The application of <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has changed to <strong>$stic_job_applications_status</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Other application statuses - Candidate 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0008', NOW(), NOW(), '1', '1', NULL, 'Example - Application other statuses (candidate)', 'Notification to the candidate when an application changes to Pending interview or Interviewed.', 'Application $stic_job_applications_status: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $stic_job_applications_stic_job_applications_contacts_name:\r\n\r\nYour application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has changed to $stic_job_applications_status.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $stic_job_applications_stic_job_applications_contacts_name:</p><p>Your application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has changed to <strong>$stic_job_applications_status</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Offer - Status change - Assigned user 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0010', NOW(), NOW(), '1', '1', NULL, 'Example - Job offer status change (assigned user)', 'Notification to the assigned user on an offer status change.', 'Offer status change: $stic_job_offers_name', '$stic_job_offers_assigned_user_name:\r\n\r\nThe offer $stic_job_offers_name has changed to $stic_job_offers_status.\r\n\r\nLink to the offer: $sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id', '<p>$stic_job_offers_assigned_user_name:</p><p>The offer <strong>$stic_job_offers_name</strong> has changed to <strong>$stic_job_offers_status</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id">Link to the offer</a>.</p>', 0, '1', 0, 'notification'),
    -- Offer - Status change - Candidates 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0011', NOW(), NOW(), '1', '1', NULL, 'Example - Job offer status change (candidates)', 'Notification to the candidates on an offer status change.', 'Offer status change: $stic_job_offers_name', 'Dear:\r\n\r\nThe offer $stic_job_offers_name has changed to $stic_job_offers_status.\r\n\r\nLink to the offer: $portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id', '<p>Dear:</p><p>The offer <strong>$stic_job_offers_name</strong> has changed to <strong>$stic_job_offers_status</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id">Link to the offer</a>.</p>', 0, '1', 0, 'notification'),
    -- Offer - Status change - Interlocutor 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0012', NOW(), NOW(), '1', '1', NULL, 'Example - Job offer status change (interlocutor)', 'Notification to the interlocutor on an offer status change.', 'Offer status change: $stic_job_offers_name', 'Dear $contact_name:\r\n\r\nThe offer $stic_job_offers_name has changed to $stic_job_offers_status.\r\n\r\nLink to the offer: $portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id', '<p>Dear $contact_name:</p><p>The offer <strong>$stic_job_offers_name</strong> has changed to <strong>$stic_job_offers_status</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id">Link to the offer</a>.</p>', 0, '1', 0, 'notification'),
    -- Private Area - Access credentials - Contact
    ('6e6f5a91-2cb9-4f42-bf26-0a13b2f1c101', NOW(), NOW(), '1', '1', NULL, 'Example - Private area access credentials (contact)', 'Notification of private area access credentials when access is activated for a contact.', 'Your private area access credentials', '$contacts_name:\r\n\r\nYour access to the private area is already enabled.\r\n\r\nUsername: $contacts_stic_pa_username_c\r\nPassword: $contacts_stic_pa_password_c\r\n\r\nYou can access it at: $portal_address', '<p>$contacts_name:</p><p>Your access to the private area is already enabled.</p><p><strong>Username:</strong> $contacts_stic_pa_username_c<br><strong>Password:</strong> $contacts_stic_pa_password_c</p><p>You can access it at: <a href="$portal_address">$portal_address</a></p>', 0, '1', 0, 'notification'),
    -- Private Area - Access credentials - Account
    ('6e6f5a91-2cb9-4f42-bf26-0a13b2f1c102', NOW(), NOW(), '1', '1', NULL, 'Example - Private area access credentials (account)', 'Notification of private area access credentials when access is activated for an account.', 'Your private area access credentials', '$accounts_name:\r\n\r\nYour access to the private area is already enabled.\r\n\r\nUsername: $accounts_stic_pa_username_c\r\nPassword: $accounts_stic_pa_password_c\r\n\r\nYou can access it at: $portal_address\r\n\r\n', '<p>$accounts_name:</p><p>Your access to the private area is already enabled.</p><p><strong>Username:</strong> $accounts_stic_pa_username_c<br><strong>Password:</strong> $accounts_stic_pa_password_c</p><p>You can access it at: <a href="$portal_address">$portal_address</a></p>', 0, '1', 0, 'notification'),
    -- Jop applications - Notification - New application submitted
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7001', NOW(), NOW(), '1', '1', NULL, 'Example - Application created (assigned user)', 'Notification to the assigned user when a new application is submitted.', 'New application received: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\n$stic_job_applications_stic_job_applications_contacts_name has submitted an application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nLink to the application: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p><strong>$stic_job_applications_stic_job_applications_contacts_name</strong> has submitted an application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href=\"$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id\">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Job applications - Notification - Application registered (candidate)
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7003', NOW(), NOW(), '1', '1', NULL, 'Example - Application created (candidate)', 'Notification to the candidate that the application has been registered.', 'Application received: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $stic_job_applications_stic_job_applications_contacts_name:\r\n\r\nWe have received your application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $stic_job_applications_stic_job_applications_contacts_name:</p><p>We have received your application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href=\"$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id\">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Message - Notification - New message in conversation
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7002', NOW(), NOW(), '1', '1', NULL, 'Example - New message in conversation (assigned user)', 'Notification to the assigned user when a private area user sends a message in a conversation.', 'New message received', '$stic_messages_assigned_user_name:\r\n\r\nYou have received a message from a private area conversation.\r\n\r\nConversation:\r\n$stic_conversations_subject\r\n\r\nMessage:\r\n$stic_messages_message\r\n\r\nLink to the message: $sugarurl/index.php?module=stic_Messages&action=DetailView&record=$stic_messages_id', '<p>$stic_messages_assigned_user_name:</p><p>You have received a message from a private area conversation.</p><p><strong>Conversation:</strong><br>$stic_conversations_subject</p><p><strong>Message:</strong><br>$stic_messages_message</p><p><a href=\"$sugarurl/index.php?module=stic_Messages&action=DetailView&record=$stic_messages_id\">Link to the message</a>.</p>', 0, '1', 0, 'notification'),
    -- Job offers - Notification - New job offer (assigned user)
    ('3c0a5f6e-1111-4f8a-9a11-3b1b7c2a0101', NOW(), NOW(), '1', '1', NULL, 'Example - New job offer (assigned user)', 'Notification to the assigned user on a job offer creation.', 'Offer created: $stic_job_offers_name', '$stic_job_offers_assigned_user_name:\r\n\r\nA new job offer has been created: $stic_job_offers_name.\r\n\r\nLink to the offer: $sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id', '<p>$stic_job_offers_assigned_user_name:</p><p>A new job offer has been created: <strong>$stic_job_offers_name</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id">Link to the offer</a>.</p>', 0, '1', 0, 'notification'),
    -- Message - Notification - New message in conversation (contact)
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7004', NOW(), NOW(), '1', '1', NULL, 'Example - New message in conversation (private area user)', 'Notification to the private area user when the assigned user sends a message in a conversation.', 'New message received', 'Dear $contact_name:\r\n\r\nYou have received a message in the private area.\r\n\r\nConversation:\r\n$stic_conversations_subject\r\n\r\nMessage:\r\n$stic_messages_message\r\n\r\nYou can view and reply to it in the private area: $portal_address/?internalpage=single_stic_chat&action=detail&id=$stic_conversations_id', '<p>Dear $contact_name:</p><p>You have received a message in the private area.</p><p><strong>Conversation:</strong><br>$stic_conversations_subject</p><p><strong>Message:</strong><br>$stic_messages_message</p><p>You can view and reply to it in the private area: <a href="$portal_address/?internalpage=single_stic_chat&action=detail&id=$stic_conversations_id">$portal_address</a>.</p>', 0, '1', 0, 'notification'),
    -- Job applications - Notification - Application presented (interlocutor)
    ('4f2c7b91-0c3e-4a2b-9b3e-7c4a9b1e9001', NOW(), NOW(), '1', '1', NULL, 'Example - Application submitted (interlocutor)', 'Notification to the interlocutor when an application changes to Submitted.', 'Application submitted: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $contact_name:\r\n\r\n$stic_job_applications_stic_job_applications_contacts_name has submitted an application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $contact_name:</p><p><strong>$stic_job_applications_stic_job_applications_contacts_name</strong> has submitted an application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Job applications - Notification - Application accepted (interlocutor)
    ('4f2c7b91-0c3e-4a2b-9b3e-7c4a9b1e9010', NOW(), NOW(), '1', '1', NULL, 'Example - Application accepted (interlocutor)', 'Notification to the interlocutor when an application changes to Accepted.', 'Application accepted: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $contact_name:\r\n\r\nThe application of $stic_job_applications_stic_job_applications_contacts_name for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has been accepted.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $contact_name:</p><p>The application of <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has been <strong>accepted</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Job applications - Notification - Application rejected or closed (interlocutor)
    ('4f2c7b91-0c3e-4a2b-9b3e-7c4a9b1e9011', NOW(), NOW(), '1', '1', NULL, 'Example - Application rejected/closed (interlocutor)', 'Notification to the interlocutor when an application changes to Rejected or closed.', 'Application rejected or closed: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $contact_name:\r\n\r\nThe application of $stic_job_applications_stic_job_applications_contacts_name for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name has been rejected or closed.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $contact_name:</p><p>The application of <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> has been <strong>rejected or closed</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Job applications - Notification - Application canceled (assigned user)
    ('4f2c7b91-0c3e-4a2b-9b3e-7c4a9b1e9002', NOW(), NOW(), '1', '1', NULL, 'Example - Application canceled (assigned user)', 'Notification to the assigned user when an application is canceled.', 'Application canceled: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\n$stic_job_applications_stic_job_applications_contacts_name has canceled the application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nLink to the application: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p><strong>$stic_job_applications_stic_job_applications_contacts_name</strong> has canceled the application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification'),
    -- Job applications - Notification - Application canceled (interlocutor)
    ('4f2c7b91-0c3e-4a2b-9b3e-7c4a9b1e9003', NOW(), NOW(), '1', '1', NULL, 'Example - Application canceled (interlocutor)', 'Notification to the interlocutor when an application is canceled.', 'Application canceled: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Dear $contact_name:\r\n\r\n$stic_job_applications_stic_job_applications_contacts_name has canceled the application for the offer $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nLink to the application: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Dear $contact_name:</p><p><strong>$stic_job_applications_stic_job_applications_contacts_name</strong> has canceled the application for the offer <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Link to the application</a>.</p>', 0, '1', 0, 'notification');


